begin;
create or replace function public.lead_filter_options() returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid:=public.lead_organization();r jsonb:='{}';group_key text;catalog_key text;is_admin boolean;begin
 if org is null then raise exception 'Operational staff required' using errcode='42501';end if;
 select exists(select 1 from public.organization_memberships where user_id=auth.uid() and organization_id=org and active and role='admin')into is_admin;
 foreach group_key in array array['brands','products','landing_pages']loop catalog_key=case group_key when 'brands' then 'brand' when 'products' then 'product' else 'landing_page' end;
 r=r||jsonb_build_object(group_key,coalesce((select jsonb_agg(x)from(select refs.value,string_agg(distinct refs.label,' / ')||case when bool_or(coalesce(c.archived,false))then ' (archived)' else '' end label from(select source_snapshot->'configured_attribution'->catalog_key->>'id' value,source_snapshot->'configured_attribution'->catalog_key->>'name' label from public.lead_ingestion where organization_id=org union all select id::text,name from public.catalog_items where organization_id=org and kind=catalog_key and is_admin)refs left join public.catalog_items c on c.organization_id=org and c.id::text=refs.value where refs.value is not null group by refs.value order by 2 limit 500)x),'[]'));
 end loop;
 return r||jsonb_build_object('sources',coalesce((select jsonb_agg(x)from(select distinct s.id::text value,s.name label from public.ingestion_sources s where s.organization_id=org and(is_admin or exists(select 1 from public.lead_ingestion i where i.source_id=s.id))order by 2 limit 500)x),'[]'),'versions',coalesce((select jsonb_agg(x)from(select distinct jsonb_build_array(v.source_id::text,v.version_key)::text value,s.form_id||' / '||case when v.version_key='' then '(unversioned legacy)' else v.version_key end label from(select source_id,coalesce(source_snapshot->>'form_version','')version_key from public.lead_ingestion where organization_id=org union select source_id,version_key from public.source_form_versions where organization_id=org and is_admin)v join public.ingestion_sources s on s.id=v.source_id order by 2 limit 500)x),'[]'),'callers',coalesce((select jsonb_agg(x)from(select distinct a.caller_id::text value,p.full_name label from public.call_attempts a join public.staff_profiles p on p.id=a.caller_id where a.organization_id=org order by 2 limit 500)x),'[]'),'confirmers',coalesce((select jsonb_agg(x)from(select distinct e.confirmed_by::text value,p.full_name label from public.confirmation_events e join public.staff_profiles p on p.id=e.confirmed_by where e.organization_id=org order by 2 limit 500)x),'[]'),'fields',(select coalesce(jsonb_agg(to_jsonb(f)),'[]')from public.quiz_columns()f),'statuses',(select coalesce(jsonb_agg(to_jsonb(s)order by sort_order,label),'[]')from public.lead_statuses s where organization_id=org));
end$$;
create trigger lead_signal after insert or update or delete on public.source_form_versions for each row execute function crm_private.signal_lead_change();
create trigger lead_signal after insert or update or delete on public.lead_statuses for each row execute function crm_private.signal_lead_change();
notify pgrst,'reload schema';commit;
